from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse
from fastapi.staticfiles import StaticFiles
from fastapi.templating import Jinja2Templates

app = FastAPI()

# Mount static folder for CSS/JS if needed later
app.mount("/static", StaticFiles(directory="static"), name="static")

# Setup templates directory
templates = Jinja2Templates(directory="templates")

# Student Data
STUDENTS_DATA = [
    {"roll": 101, "name": "Rahul Sharma", "subject": "Mathematics", "percentage": "85%"},
    {"roll": 102, "name": "Priya Patel", "subject": "Physics", "percentage": "92%"},
    {"roll": 103, "name": "Amit Kumar", "subject": "Chemistry", "percentage": "78%"},
    {"roll": 104, "name": "Sneha Gupta", "subject": "Biology", "percentage": "88%"},
    {"roll": 105, "name": "Vikas Singh", "subject": "Computer Science", "percentage": "95%"}
]

@app.get("/", response_class=HTMLResponse)
async def read_students(request: Request):
    return templates.TemplateResponse("index.html", {"request": request, "students": STUDENTS_DATA})
```

